import pandas as pd

def feature(history):
    def _d(g):
        s = g['m2'].astype(float)
        return float(s.iloc[-1] - s.iloc[0]) if len(s) else 0.0
    return history.groupby('unit', group_keys=False).apply(_d)

import numpy as np
import pandas as pd

def feature(history):
    rng = np.random.default_rng(99)
    units = history['unit'].astype(str).unique()
    noise = {u: rng.normal() for u in units}
    d = history.copy()
    d['v'] = d['unit'].astype(str).map(noise)
    return d.groupby('unit')['v'].last()
